tool.output_format:
Returns: {
  "results": [
    {
      "source": string,      // e.g., "man:rsync", "arch:systemd"
      "source_type": string, // "man", "arch", "doc", etc.
      "title": string,
      "content": string,
      "relevance": float,    // 0.0 to 1.0
      "url": string          // Optional source URL
    }
  ],
  "query": string
}
